    tplManagement: 'Gestion du trade (break-even, partiels, trailing)',
    tplReview: 'Revue hebdo : ce qui a marché, quelle erreur j\'ai répétée',
    tplCommit: 'Je m\'engage à trader UNIQUEMENT quand toute ma checklist est remplie. Sans exception.',
    tplPrintBtn: 'Imprimer / PDF',
