    simuladorDesc_ed004: 'Ouvrez le simulateur et testez comment le passage du temps (Theta) ou un pic de volatilité (Vega) affectent votre position avant de risquer du capital réel.',
    abrirSimulador_ed005: 'OUVRIR SIMULATEUR',
    edu_fundamentosComprarVsVende_6227e3cc: 'Fondamentaux : Acheter vs Vendre des Options',
    edu_todaOperacionConOpciones_4b806806: 'Toute opération sur options comporte DEUX PARTIES. Celui qui ACHÈTE (Long) paie la prime et obtient un droit. Celui qui VEND (Short) encaisse la prime et accepte l\'obligation si elle est exercée.',
    edu_lasGriegas_0ebfaf86: 'Les Grecques',
    edu_lasGriegasCuantificanLa_560a7bae: 'Les grecques quantifient la sensibilité de la prime face à différents facteurs. Les maîtriser est ce qui sépare le trader professionnel de l\'amateur.',
    edu_moneynessItmAtmOtm_a4a14296: 'Moneyness : ITM / ATM / OTM (expliqué)',
    edu_laMoneynessIndicaLa_d33c00c2: 'La MONEYNESS indique la relation entre le prix actuel du sous-jacent (Spot S) et le Strike K. Elle définit la valeur intrinsèque de l\'option et son comportement.',
    edu_volatilidadImplicitaIv_9566fdd4: 'Volatilité Implicite (IV)',
    edu_laIvEsEl_8e2ceb1e: 'L\'IV est le prix du marché pour l\'incertitude future. Une IV élevée renchérit les primes ; une IV faible les diminue. C\'est le facteur LE PLUS important après Delta.',
    edu_comoLeerElDiagrama_0e91a1f2: 'Comment lire le diagramme de Payoff',
    edu_elGraficoDePayoff_4228af6d: 'Le graphique de payoff montre le PnL (axe Y) en fonction du prix du sous-jacent à l\'expiration (axe X). Les deux lignes clés sont T+0 (aujourd\'hui) et At Expiry (expiration).',
    edu_longCallBuyCall_b69bddbc: 'LONG CALL (BUY CALL) → Vous payez la prime. Vous gagnez si ça monte > Strike+Prima. Perte maximale = prime payée.',
    edu_longPutBuyPut_0125f4de: 'LONG PUT (BUY PUT) → Vous payez la prime. Vous gagnez si ça baisse < Strike−Prima. Perte maximale = prime payée.',
    edu_shortCallSellCall_46b9297a: 'SHORT CALL (SELL CALL) → Vous encaissez la prime. Vous perdez si ça monte > Strike+Prima. Perte maximale = ILLIMITÉE (si naked).',
    edu_shortPutSellPut_cc28336a: 'SHORT PUT (SELL PUT) → Vous encaissez la prime. Vous perdez si ça baisse < Strike−Prima. Perte maximale = Strike−Prima si tombe à 0.',
    edu_regla802080_db62e282: 'RÈGLE 80/20 → ~80% des options expirent sans valeur → statistiquement le vendeur de primes gagne souvent ; mais son ratio risque/bénéfice est mauvais.',
    edu_deltaCambioEnPrima_0791393e: 'Delta Δ → Changement de la prime par $1 de mouvement du sous-jacent. Calls : 0 à +1. Puts : 0 à -1.',
    edu_thetaPerdidaDeValor_c24fe104: 'Theta Θ → Perte de valeur temporelle pour chaque jour écoulé. Toujours négative pour Long, positive pour Short.',
    edu_vegaSensibilidadAlCambio_49f4d565: 'Vega ν → Sensibilité au changement de la volatilité implicite (IV). Positive pour Long, négative pour Short.',
    edu_gammaVelocidadDeCambio_2647e1e9: 'Gamma Γ → Vitesse de changement du Delta ; maximum près de ATM. Longs : Gamma positif. Shorts : Gamma négatif.',
    edu_rhoSensibilidadACambios_6dd807ab: 'Rho ρ → Sensibilité aux changements de taux d\'intérêt. Significative seulement pour les options à long terme (LEAPS).',
    edu_call_094692fa: '── CALL ──',
    edu_itmInTheMoney_d20317a8: 'ITM (In-The-Money) → S > K. Possède une valeur intrinsèque = S−K. Delta > 0.5. Comportement "comme une action".',
    edu_atmAtTheMoney_638c9e7d: 'ATM (At-The-Money) → S ≈ K. Sans valeur intrinsèque ; uniquement valeur temporelle. Delta ≈ 0.5. Gamma et Vega maximaux.',
    edu_otmOutOfThe_2b67777e: 'OTM (Out-of-The-Money) → S < K. Sans valeur intrinsèque ; uniquement valeur temporelle. Delta < 0.5. Moins chère mais plus risquée.',
    edu_put_a27fa8fc: '── PUT ──',
    edu_itmInTheMoney_bfd445a5: 'ITM (In-The-Money) → S < K. Possède une valeur intrinsèque = K−S. Delta < −0.5.',
    edu_atmAtTheMoney_793be97c: 'ATM (At-The-Money) → S ≈ K. Aucune valeur intrinsèque ; seulement valeur temporelle. Delta ≈ −0.5.',
    edu_otmOutOfThe_71ddb79d: 'OTM (Out-of-The-Money) → S > K. Aucune valeur intrinsèque ; seulement valeur temporelle. Delta > −0.5.',
    edu_cLculoDelPayoff_2fb38b8e: '── CALCUL DU PAYOFF À L\'ÉCHÉANCE ──',
    edu_longCallPnlMax_e997a851: 'Long Call:  PnL = max(0, S−K) × 100 × contrats − prima_payée × 100',
    edu_longPutPnlMax_80f585a4: 'Long Put:   PnL = max(0, K−S) × 100 × contrats − prima_payée × 100',
    edu_shortCallPnlPrima_d573157a: 'Short Call: PnL = prima_encaissée × 100 − max(0, S−K) × 100 × contrats',
    edu_shortPutPnlPrima_47fd35c2: 'Short Put:  PnL = prima_encaissée × 100 − max(0, K−S) × 100 × contrats',
    edu_ivRankIvPercentile_da54acc4: 'IV Rank / IV Percentile → Contextualisent l\'IV actuelle vs. historique (52 dernières semaines).',
    edu_crushPostEarningsLa_c269719f: 'Crush post-earnings → L\'IV s\'effondre après l\'événement ; les acheteurs perdent souvent même s\'ils ont raison sur la direction.',
    edu_vegaLongVsShort_404de31c: 'Vega Long vs. Short → Les acheteurs gagnent si l\'IV monte ; les vendeurs si elle baisse.',
    edu_reglaPracticaComprarOpcio_98a9dbf8: 'Règle pratique : ACHETER options avec IV basse (IV Rank < 30), VENDRE avec IV haute (IV Rank > 50).',
    edu_skewLasPutsOtm_02473640: 'Skew → Les puts OTM ont généralement une IV plus élevée que les calls OTM (peur des baisses).',
    edu_lineaVerdeCurrentP_ecfc0457: 'Ligne VERTE (Current P&L) → Votre PnL théorique AUJOURD\'HUI à différents prix utilisant Black-Scholes (inclut valeur temporelle).',
    edu_lineaBlancaPunteadaAt_8a5c4ef9: 'Ligne BLANCHE pointillée (At Expiry) → PnL SI vous conservez jusqu\'à l\'échéance (sans valeur temporelle).',
    edu_lineaNaranjaSpotPrecio_de21f24f: 'Ligne ORANGE (Spot) → Prix actuel du sous-jacent. Référence principale.',
    edu_lineaVioletaBreakEven_9112e631: 'Ligne VIOLETTE (Break-Even) → Point où PnL = 0 à l\'échéance. Au-dessus/en dessous vous gagnez.',
    edu_zonaVerdeRangoDe_49e82b2d: 'Zone VERTE → Plage de prix où vous terminez avec un profit. Zone ROUGE → Pertes.',
    edu_zonasDeMoneynessNuevas_d71f9261: 'ZONES DE MONEYNESS (nouvelles) → Vert clair = ITM, Jaune = ATM, Rouge clair = OTM. Aide à visualiser où se trouve chaque strike.',
    edu_laDiferenciaEntreAmbas_439232b3: 'La DIFFÉRENCE entre les deux lignes = valeur extrinsèque (temps + IV). Theta négatif la réduit chaque jour.',
    gd_leerElGrafico_01e33326: 'Lire le graphique',
    gd_laLineaAzulMuestra_94ffef2a: 'La ligne bleue montre votre P&L actuel (T+0). La ligne blanche est votre P&L à l\'échéance. Les zones verte/rouge indiquent les zones de profit/perte.',
    gd_delta_2772f4ee: 'Delta Δ',
